SELECT CASE WHEN rating >= 4.4 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, APPROX_PERCENTILE(rating, 0.95) AS rating_p95, APPROX_PERCENTILE(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles, APPROX_PERCENTILE(rating, 0.95) AS rating_p95_2, AVG(rating) AS avg_rating, PERCENTILE_APPROX(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles_2 FROM suppliers GROUP BY rating_tier ORDER BY rating_p95_2;
